import{_ as s,o as t,c as i,a0 as e}from"./chunks/framework.DhQjJcnt.js";const k=JSON.parse('{"title":"协议规范","description":"","frontmatter":{},"headers":[],"relativePath":"protocol.md","filePath":"protocol.md","lastUpdated":1787985369000}'),n={name:"protocol.md"};function l(o,a,d,p,h,c){return t(),i("div",null,[...a[0]||(a[0]=[e(`<h1 id="协议规范" tabindex="-1">协议规范 <a class="header-anchor" href="#协议规范" aria-label="Permalink to &quot;协议规范&quot;">​</a></h1><p>本文档面向想要实现兼容客户端/服务器、或深入理解内部机制的开发者。所有协议均为简单文本/二进制格式，无加密（<code>--key</code> 加密在 FRS1 层，见下文）。</p><h2 id="_1-信令-rest-api" tabindex="-1">1. 信令 REST API <a class="header-anchor" href="#_1-信令-rest-api" aria-label="Permalink to &quot;1. 信令 REST API&quot;">​</a></h2><p>Base URL：<code>signaling_addr</code>（如 <code>http://host:8080</code>）。</p><h3 id="post-room-create" tabindex="-1">POST <code>/room/create</code> <a class="header-anchor" href="#post-room-create" aria-label="Permalink to &quot;POST \`/room/create\`&quot;">​</a></h3><p>请求：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;prefix&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;game&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ttl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">43200</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;addr&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;223.117.153.115:44276&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>prefix</code></td><td>房间前缀</td></tr><tr><td><code>ttl</code></td><td>有效秒数</td></tr><tr><td><code>addr</code></td><td>发起者经 UDP 探测得到的公网地址</td></tr></tbody></table><p>响应 <code>200</code>：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;room_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;game-a3f9c2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;host_addr&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;223.117.153.115:44276&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><h3 id="get-room-id" tabindex="-1">GET <code>/room/{id}</code> <a class="header-anchor" href="#get-room-id" aria-label="Permalink to &quot;GET \`/room/{id}\`&quot;">​</a></h3><p>响应 <code>200</code>：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;room_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;game-a3f9c2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;host_addr&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;223.117.153.115:44276&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;guest_addr&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;223.117.153.115:44282&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;created_at&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1724900000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;expires_at&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1724943200</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>guest_addr</code> 在访客加入前为 <code>null</code>。房间过期返回 <code>404</code>。</p><h3 id="post-room-id-join" tabindex="-1">POST <code>/room/{id}/join</code> <a class="header-anchor" href="#post-room-id-join" aria-label="Permalink to &quot;POST \`/room/{id}/join\`&quot;">​</a></h3><p>请求：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;addr&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;223.117.153.115:44282&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>响应 <code>200</code>：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;room_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;game-a3f9c2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;host_addr&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;223.117.153.115:44276&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><h3 id="delete-room-id" tabindex="-1">DELETE <code>/room/{id}</code> <a class="header-anchor" href="#delete-room-id" aria-label="Permalink to &quot;DELETE \`/room/{id}\`&quot;">​</a></h3><p><code>204</code> 成功，<code>404</code> 不存在。</p><h3 id="get-health" tabindex="-1">GET <code>/health</code> <a class="header-anchor" href="#get-health" aria-label="Permalink to &quot;GET \`/health\`&quot;">​</a></h3><p>返回 <code>ok</code>。</p><h2 id="_2-udp-公网探测" tabindex="-1">2. UDP 公网探测 <a class="header-anchor" href="#_2-udp-公网探测" aria-label="Permalink to &quot;2. UDP 公网探测&quot;">​</a></h2><p>客户端向探测端口（与 HTTP 同端口，或 <code>signaling_udp</code>）发送：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ECHO &lt;token&gt;</span></span></code></pre></div><p>服务端回显（源地址即客户端经 NAT 的公网映射）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ADDR &lt;token&gt; &lt;ip&gt;:&lt;port&gt;</span></span></code></pre></div><p><code>token</code> 由客户端生成（8 位 hex），用于关联响应。</p><h2 id="_3-打洞协议" tabindex="-1">3. 打洞协议 <a class="header-anchor" href="#_3-打洞协议" aria-label="Permalink to &quot;3. 打洞协议&quot;">​</a></h2><p>数据报均为 ASCII 文本：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PUNCH &lt;token&gt;   # 打洞请求</span></span>
<span class="line"><span>ACK &lt;token&gt;     # 打洞确认（token 回显）</span></span></code></pre></div><table tabindex="0"><thead><tr><th>场景</th><th>行为</th></tr></thead><tbody><tr><td>收到 <code>PUNCH &lt;t&gt;</code></td><td>回 <code>ACK &lt;t&gt;</code>（带重试），记录对端地址 → 直连</td></tr><tr><td>收到 <code>ACK &lt;t&gt;</code> 且 <code>t</code> 与本地 token 一致</td><td>直连成功</td></tr><tr><td>收到 FRS1 帧（magic <code>FRS1</code>）</td><td>对端已进入数据阶段 → 直连成功</td></tr></tbody></table><p>打洞目标 = 对端通告地址 ± spread 端口（排除自身端口）。窗口约 3 秒。</p><h2 id="_4-frs1-可靠流协议" tabindex="-1">4. FRS1 可靠流协议 <a class="header-anchor" href="#_4-frs1-可靠流协议" aria-label="Permalink to &quot;4. FRS1 可靠流协议&quot;">​</a></h2><p>UDP 数据报，15 字节头 + 负载：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>偏移  长度  字段</span></span>
<span class="line"><span>0     4     magic = &quot;FRS1&quot;</span></span>
<span class="line"><span>4     1     flags: 0x01=DATA, 0x02=FIN, 0=纯ACK</span></span>
<span class="line"><span>5     4     seq (u32 BE)</span></span>
<span class="line"><span>9     4     ack (u32 BE)   — 已连续接收的最大序号+1</span></span>
<span class="line"><span>13    2     len (u16 BE)   — 负载长度</span></span>
<span class="line"><span>15    len   负载（DATA 帧；--key 时密文含 16B Poly1305 标签）</span></span></code></pre></div><h3 id="发送方状态机" tabindex="-1">发送方状态机 <a class="header-anchor" href="#发送方状态机" aria-label="Permalink to &quot;发送方状态机&quot;">​</a></h3><ul><li><code>next_seq</code> 从 1 递增；窗口 32 帧</li><li>数据帧入窗即发送，入窗帧存入重传队列</li><li>收到 <code>ack=N</code>：移除所有 <code>seq &lt; N</code> 的帧；FIN 帧被确认（<code>ack &gt; fin_seq</code>）则关闭完成</li><li>150ms 定时器：重传窗口内所有未确认帧</li><li>空闲 1s：发送纯 ACK 帧（keepalive，维持 NAT 映射）</li></ul><h3 id="接收方状态机" tabindex="-1">接收方状态机 <a class="header-anchor" href="#接收方状态机" aria-label="Permalink to &quot;接收方状态机&quot;">​</a></h3><ul><li><code>next_expected</code> 从 1 开始</li><li>收到 <code>seq == next_expected</code> 的数据帧：投递负载、<code>next_expected += 1</code>、回 ACK</li><li>乱序/重复帧：丢弃（go-back-N），仍回 ACK 提示发送方</li><li>收到 FIN：置 <code>rx_closed</code>，回 ACK</li><li>读缓冲满（1MB）：丢弃帧不推进序号（触发重传 = 流控）</li></ul><h3 id="加密" tabindex="-1">加密 <a class="header-anchor" href="#加密" aria-label="Permalink to &quot;加密&quot;">​</a></h3><p><code>--key</code> 启用时，DATA 帧负载 = <code>ChaCha20-Poly1305.encrypt(nonce=seq, plaintext)</code>，密文含 16 字节认证标签；单帧明文上限 1184 字节。ACK/FIN 帧不加密。</p><h3 id="关闭" tabindex="-1">关闭 <a class="header-anchor" href="#关闭" aria-label="Permalink to &quot;关闭&quot;">​</a></h3><ul><li><code>shutdown()</code>：发 FIN 帧（<code>seq = next_seq</code>，入重传队列），等待 <code>ack &gt; fin_seq</code></li><li>5 秒未确认：视为对端消失，<strong>尽力关闭</strong>（不报错）</li></ul><h3 id="错误处理" tabindex="-1">错误处理 <a class="header-anchor" href="#错误处理" aria-label="Permalink to &quot;错误处理&quot;">​</a></h3><ul><li>Windows <code>WSAECONNRESET(10054)</code> / <code>WSAECONNREFUSED(10061)</code>：忽略（ICMP 毒化）</li><li>对端 socket 关闭：后续 recv 返回错误 → 会话结束</li></ul><h2 id="_5-隧道帧协议" tabindex="-1">5. 隧道帧协议 <a class="header-anchor" href="#_5-隧道帧协议" aria-label="Permalink to &quot;5. 隧道帧协议&quot;">​</a></h2><p>FRS1 流（或中继 TCP 流）之上的字节流，用于本地 TCP 桥接与多连接复用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>访客 → 房主: &quot;CNEW&quot;                          # 4 字节，新连接</span></span>
<span class="line"><span>访客 → 房主: [u32 len BE][payload]            # 数据帧，len ≤ 1 MiB</span></span>
<span class="line"><span>访客 → 房主: [u32 0]                          # 结束帧</span></span>
<span class="line"><span>房主 → 访客: [u32 len BE][payload]            # 数据帧</span></span>
<span class="line"><span>房主 → 访客: [u32 0]                          # 结束帧</span></span></code></pre></div><ul><li>房主等待 <code>CNEW</code> 时收到的非 <code>CNEW</code> 4 字节按「残余数据帧头」处理并跳过（关闭竞态保护）</li><li>结束帧对称确认：本地关闭发结束帧并等待对端；收到结束帧即回送（若未发送）并结束本连接</li></ul><h2 id="_6-中继协议" tabindex="-1">6. 中继协议 <a class="header-anchor" href="#_6-中继协议" aria-label="Permalink to &quot;6. 中继协议&quot;">​</a></h2><p>TCP 文本行协议（<code>\\r\\n</code> 结尾）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端 → 服务器: HELLO &lt;room_id&gt; &lt;HOST|GUEST&gt;</span></span>
<span class="line"><span>服务器 → 客户端: WAIT\\r\\n | OK\\r\\n | ERROR &lt;原因&gt;\\r\\n</span></span></code></pre></div><table tabindex="0"><thead><tr><th>响应</th><th>含义</th></tr></thead><tbody><tr><td><code>WAIT</code></td><td>已入槽，等待对端</td></tr><tr><td><code>OK</code></td><td>对端已在等待，已配对</td></tr><tr><td><code>ERROR ROOM_EXPIRED</code> / <code>ERROR BAD_HELLO</code> / <code>ERROR BAD_ROLE</code> / <code>ERROR ALREADY_CONNECTED</code> / <code>ERROR NO_PEER</code></td><td>拒绝</td></tr></tbody></table><p>配对成功后服务器对两端 socket 双向拷贝，客户端无感知。配对等待上限 10 分钟。</p><h2 id="兼容性说明" tabindex="-1">兼容性说明 <a class="header-anchor" href="#兼容性说明" aria-label="Permalink to &quot;兼容性说明&quot;">​</a></h2><ul><li>打洞与中继阶段均为 ASCII/二进制直读，便于抓包调试</li><li>若需与 frp 等工具互通：frp-sh 协议为自研，<strong>不兼容</strong> frp 协议</li></ul>`,58)])])}const E=s(n,[["render",l]]);export{k as __pageData,E as default};
